"""docs/reference/commands.md is generated by scripts/commands_reference.py and must stay fresh.

Building the page imports the whole CLI once (about five seconds); the catalogue is loaded once
per test session and reused.
"""

from __future__ import annotations

from functools import cache
from pathlib import Path
from typing import Any

import commands_reference

ROOT = Path(__file__).parents[2]


@cache
def _cli() -> tuple[list[dict[str, Any]], dict[str, str]]:
    return commands_reference.load_cli()


def test_committed_commands_reference_is_fresh() -> None:
    committed = (ROOT / commands_reference.OUTPUT).read_text(encoding="utf-8")
    assert committed == commands_reference.render(*_cli()), (
        "docs/reference/commands.md no longer matches the CLI; run: "
        "uv run python scripts/commands_reference.py and commit the result"
    )


def test_every_command_has_one_line_in_its_group_section() -> None:
    catalog, descriptions = _cli()
    text = commands_reference.render(catalog, descriptions)
    for entry in catalog:
        group = entry["id"].split(" ", 1)[0]
        assert f"\n## alpha {group}\n" in text
        assert sum(line.startswith(f"- `alpha {entry['id']}") for line in text.splitlines()) >= 1
    assert all(len(line) <= commands_reference.MAX_LINE for line in text.splitlines())


def test_command_line_keeps_required_options_and_counts_the_rest() -> None:
    options = [{"flag": f"--option-number-{i}", "required": False} for i in range(30)] + [
        {"flag": "--needed", "required": True},
        {"flag": "--help", "required": False},
    ]
    line = commands_reference.command_line(
        {"id": "research case create", "args": [{"name": "project_id"}], "options": options},
        "Create one governed research case for a project. More text follows here.",
    )
    assert line.startswith("- `alpha research case create <PROJECT_ID>` — Create one governed")
    assert "`--needed (required)`" in line and "--help" not in line
    assert line.endswith("more") and len(line) <= 160


def test_first_phrase_is_one_sentence_without_markup() -> None:
    assert commands_reference.first_phrase("Run `x` now. Then more.\n\nDetails.") == "Run 'x' now."
    assert commands_reference.first_phrase(None) == "(no description)"
